options(stringsAsFactors=FALSE,survey.lonely.psu='adjust');base<-'.';root<-file.path(base,'TB_metabolome_exposome_20261115_2130');out<-file.path(base,'NHANES_TB_Stage3_Inference_Audit_20261116');.libPaths(c(file.path(root,'analysis_MWAS_ExWAS/Rlib'),.libPaths()));library(haven);library(survey);raw<-file.path(base,'NHANES离线数据库/nhanes1999-2020数据合集/2011-2012');q<-read.csv(file.path(base,'系统复审与优化_20261116/数据表/01_candidate_registry.csv'));files<-list.files(raw,pattern='[.]xpt$',recursive=TRUE,full.names=TRUE);files<-files[!grepl('/[.]_',files)];tables<-unique(c(q$source_table,'demo_g','tb_g','tbx_g','smq_g','bmx_g','whq_g','tbq_g','biopro_g'));fs<-files[tolower(tools::file_path_sans_ext(basename(files)))%in%tables];inventory<-list();parts<-list();for(f in fs){d<-as.data.frame(read_xpt(f));stopifnot(!anyDuplicated(d$SEQN));inventory[[length(inventory)+1]]<-data.frame(file=f,md5=unname(tools::md5sum(f)),n=nrow(d),variables=ncol(d));parts[[tolower(tools::file_path_sans_ext(basename(f)))]]<-d};a<-parts$demo_g;duplicates<-list();for(nm in setdiff(names(parts),'demo_g')){d<-parts[[nm]];m<-match(a$SEQN,d$SEQN);for(v in setdiff(names(d),'SEQN')){if(v%in%names(a)){x<-as.numeric(a[[v]]);y<-as.numeric(d[[v]][m]);duplicates[[length(duplicates)+1]]<-data.frame(file=nm,variable=v,n_conflict=sum(!is.na(x)&!is.na(y)&x!=y));}else a[[v]]<-d[[v]][m]}};write.csv(do.call(rbind,inventory),file.path(out,'数据/01_XPT清单及指纹.csv'),row.names=FALSE);write.csv(do.call(rbind,duplicates),file.path(out,'数据/02_重复变量检查.csv'),row.names=FALSE)
a$age<-a$RIDAGEYR;a$sex_male<-as.integer(a$RIAGENDR==1);a$race<-factor(c('Mexican American','Other Hispanic','Non-Hispanic White','Non-Hispanic Black','Other/Multi')[a$RIDRETH1],levels=c('Non-Hispanic White','Mexican American','Other Hispanic','Non-Hispanic Black','Other/Multi'));e<-a$DMDEDUC2;a$educ<-factor(ifelse(e%in%1:2,'<High school',ifelse(e==3,'High school/GED',ifelse(e%in%4:5,'>High school',NA))),levels=c('>High school','High school/GED','<High school'));a$PIR<-a$INDFMPIR;a$birth<-factor(ifelse(a$DMDBORN4==1,'US',ifelse(a$DMDBORN4%in%c(2,3),'NonUS',NA)),levels=c('US','NonUS'));a$smoking<-factor(ifelse(a$SMQ020==2,'Never',ifelse(a$SMQ020==1&a$SMQ040==3,'Former',ifelse(a$SMQ020==1&a$SMQ040%in%1:2,'Current',NA))),levels=c('Never','Former','Current'));a$QFT<-ifelse(a$LBXTBIN%in%c(1,2),as.integer(a$LBXTBIN==1),NA);a$TST10<-ifelse(!is.na(a$TBDRUIND)&a$TBDRUIND>=0&a$TBDRUIND<=86,as.integer(a$TBDRUIND>=10),NA);a$group<-ifelse(!is.na(a$QFT)&!is.na(a$TST10),paste0('Q',a$QFT,'T',a$TST10),NA);a$y<-ifelse(a$group=='Q1T0',1,ifelse(a$group=='Q0T1',0,NA));a$x<-ifelse(a$LBXBCD>0,log2(a$LBXBCD),NA);a$logcot<-ifelse(a$LBXCOT>0,log2(a$LBXCOT),NA);a$logucr<-ifelse(a$URXUCR>0,log2(a$URXUCR),NA);cv<-c('age','sex_male','race','educ','PIR','birth','smoking');eligible<-is.finite(a$WTMEC2YR)&a$WTMEC2YR>0;mask<-a$age>=20&!is.na(a$y)&complete.cases(a[,c('x',cv)]);mask[is.na(mask)]<-FALSE;a$.dom<-mask;des<-svydesign(ids=~SDMVPSU,strata=~SDMVSTRA,weights=~WTMEC2YR,nest=TRUE,data=a[eligible,]);dom<-subset(des,.dom);f<-y~x+age+sex_male+race+educ+PIR+birth+smoking;fit<-svyglm(f,dom,family=quasibinomial());saveRDS(list(data=a,design=des,domain=dom,fit=fit,mask=mask,q=q),file.path(out,'数据/rebuilt_private.rds'));b<-coef(fit)['x'];se<-sqrt(vcov(fit)['x','x']);z<-b/se;prior<-read.csv(file.path(base,'系统复审与优化_20261116/数据表/02_all_marker_four_phenotype_results.csv'));prior<-subset(prior,layer=='exposome');ans<-list();for(method in c('design_t','residual_t','normal')){df<-switch(method,design_t=degf(dom),residual_t=fit$df.residual,normal=Inf);crit<-if(is.finite(df))qt(.975,df)else qnorm(.975);pv<-if(is.finite(df))2*pt(-abs(z),df)else 2*pnorm(-abs(z));pp<-if(method=='design_t')2*pt(-abs(prior$b/prior$se),prior$df)else if(method=='residual_t')2*pt(-abs(prior$b/prior$se),prior$df_residual)else 2*pnorm(-abs(prior$b/prior$se));pp[prior$status!='ok'|!is.finite(pp)]<-1;qq<-p.adjust(pp,'BH');ans[[method]]<-data.frame(method=method,b=unname(b),se=se,statistic=unname(z),df=df,p=unname(pv),OR=unname(exp(b)),low=unname(exp(b-crit*se)),high=unname(exp(b+crit*se)),q_183=qq[prior$variable=='LBXBCD'],n=nrow(dom$variables),events=sum(dom$variables$y),PSUs=length(unique(interaction(dom$variables$SDMVSTRA,dom$variables$SDMVPSU))),strata=length(unique(dom$variables$SDMVSTRA)),rank=fit$rank)};write.csv(do.call(rbind,ans),file.path(out,'数据/03_三种推断.csv'),row.names=FALSE)
old<-as.data.frame(readRDS(file.path(root,'analysis_MWAS_ExWAS/derived/analysis_2011-2012.rds')));old<-old[match(a$SEQN,old$SEQN),];compare<-list();for(v in intersect(c('age','sex_male','race','educ','PIR','QFT','TST10','LBXBCD','LBXBPB','LBXTHG','WTMEC2YR','SDMVPSU','SDMVSTRA'),names(old))){x<-as.character(a[[v]]);y<-as.character(old[[v]]);bad<-xor(is.na(x),is.na(y))|(!is.na(x)&!is.na(y)&x!=y);compare[[v]]<-data.frame(variable=v,n_mismatch=sum(bad),n_na_new=sum(is.na(x)),n_na_old=sum(is.na(y)));if(any(bad))write.csv(data.frame(SEQN=a$SEQN[bad],new=x[bad],old=y[bad]),file.path(out,paste0('数据/mismatch_',v,'.csv')),row.names=FALSE)};write.csv(do.call(rbind,compare),file.path(out,'数据/04_原派生值核验.csv'),row.names=FALSE)
flow<-data.frame(step=c('DEMO全体','成人MEC','有效QFT','有效TST且QFT','两种单阳性','血镉有效','全部主模型完整'),n=c(nrow(a),sum(a$age>=20&eligible),sum(a$age>=20&eligible&!is.na(a$QFT)),sum(a$age>=20&eligible&!is.na(a$group)),sum(a$age>=20&eligible&!is.na(a$y)),sum(a$age>=20&eligible&!is.na(a$y)&!is.na(a$x)),sum(mask&eligible)));write.csv(flow,file.path(out,'数据/05_STROBE.csv'),row.names=FALSE);capture.output(sessionInfo(),file=file.path(out,'日志/sessionInfo.txt'));print(do.call(rbind,ans));print(flow)
